    $offset = [Convert]::ToInt32($line.Substring(3, 4), 16)
    $recordType = [Convert]::ToInt32($line.Substring(7, 2), 16)

    if ($recordType -eq 0) {
      $recordEnd = $baseAddress + $offset + $byteCount
      if ($recordEnd -gt $maxAddress) {
        $maxAddress = $recordEnd
      }
    } elseif ($recordType -eq 4) {
      $baseAddress = [Convert]::ToInt32($line.Substring(9, 4), 16) -shl 16
    }
  }

  return $maxAddress
}

