$internalFlashEnd = 0x08000000 + 128KB
if ($maxAddress -gt $internalFlashEnd) {
  $maxHex = "0x{0:x8}" -f $maxAddress
  throw "OpenOCD cannot program firmware larger than STM32H750B-DK internal flash (128 KB). Current HEX reaches $maxHex, past 0x08020000. Reduce the image below 128 KB, or rebuild it for a QSPI/external-flash boot flow before flashing."
}

$resolvedHex = (Resolve-Path -LiteralPath $HexPath).Path -replace "\\", "/"

& $OpenOcdBin `
  -s $OpenOcdScripts `
  -f interface/stlink.cfg `
  -f target/stm32h7x.cfg `
  -c "transport select swd" `
  -c "program $resolvedHex verify reset exit"

if ($LASTEXITCODE -ne 0) {
  exit $LASTEXITCODE
}

