    -s $OpenOcdScripts `
    -f board/stm32h750b-disco.cfg `
    -c "init" `
    -c "reset init" `
    -c "program $resolvedHex verify" `
    -c "program $resolvedBootStubHex verify" `
    -c "reset run" `
    -c "shutdown"
} else {
  $mainRange = Get-IntelHexAddressRange $HexPath
